var e=(t,a)=>({en:t,fa:a}),n=[{id:"core",icon:"shield",title:e("Core Principles","اصول بنیادین"),intro:e("These five rules outrank everything else on this page. If a situation is not covered below, judge it against these.","این پنج قانون بر تمام موارد دیگر ارجحیت دارند."),items:[{n:"1.1",t:e("Value your life","به زندگی خود ارزش بگذارید"),d:e("Your character fears death, injury and loss exactly like a real person would. Acting fearless with a gun to your head is the single most common reason people are removed.","شخصیت شما دقیقاً مانند یک انسان واقعی از مرگ و آسیب می‌ترسد."),p:e("Verbal warning, then 1-3 days","تذکر، سپس ۱ تا ۳ روز")},{n:"1.2",t:e("No random deathmatch (RDM)","بدون قتل تصادفی"),d:e("You need a roleplay reason and an interaction before violence. Shooting someone you have never spoken to is never acceptable.","برای خشونت به دلیل نقش‌آفرینی و تعامل قبلی نیاز دارید."),p:e("3-7 days, permanent if repeated","۳ تا ۷ روز، دائمی در صورت تکرار")},{n:"1.3",t:e("No vehicle deathmatch (VDM)","بدون زیر گرفتن عمدی"),d:e("A car is not a weapon of convenience. Running people down without an established conflict is treated as RDM.","خودرو ابزار کشتن نیست."),p:e("3-7 days","۳ تا ۷ روز")},{n:"1.4",t:e("No metagaming","بدون متاگیمینگ"),d:e("Information from Discord, streams or a friend on voice does not exist to your character. If you did not learn it in-game, you do not know it.","اطلاعات خارج از بازی برای شخصیت شما وجود ندارد."),p:e("3 days, permanent if coordinated","۳ روز، دائمی در صورت هماهنگی")},{n:"1.5",t:e("No powergaming","بدون پاورگیمینگ"),d:e("You cannot force an outcome on another player or perform actions your character realistically could not. Give others a chance to respond.","نمی‌توانید نتیجه را به بازیکن دیگر تحمیل کنید."),p:e("1-5 days","۱ تا ۵ روز")}]},{id:"conduct",icon:"users",title:e("Player Conduct","رفتار بازیکن"),intro:e("Out-of-character behaviour between people, not characters.","رفتار خارج از نقش میان افراد."),items:[{n:"2.1",t:e("Zero tolerance for hate","عدم تحمل نفرت"),d:e('Racism, homophobia, transphobia, religious hatred and slurs of any kind end your time here immediately. There is no "it was in character" exception.',"نژادپرستی و هر نوع توهین نفرت‌آمیز بلافاصله منجر به اخراج می‌شود."),p:e("Permanent, no appeal","دائمی، بدون تجدیدنظر")},{n:"2.2",t:e("No harassment","بدون آزار"),d:e("Targeting a specific player repeatedly, following them across sessions, or taking conflict to their private accounts is harassment.","هدف قرار دادن مکرر یک بازیکن آزار محسوب می‌شود."),p:e("7 days to permanent","۷ روز تا دائمی")},{n:"2.3",t:e("Keep OOC out of IC","تفکیک درون و بیرون نقش"),d:e("Arguments about rules, lag or staff decisions belong in a ticket, not in the middle of a scene.","بحث درباره قوانین در تیکت انجام می‌شود، نه وسط صحنه."),p:e("Warning, then 1 day","تذکر، سپس ۱ روز")},{n:"2.4",t:e("Minimum age is 16","حداقل سن ۱۶ سال"),d:e("This community handles mature themes. If you are under 16 you cannot play here, regardless of maturity.","این جامعه موضوعات بزرگسال دارد."),p:e("Removal until eligible","حذف تا رسیدن به سن مجاز")}]},{id:"crime",icon:"siren",title:e("Crime & Conflict","جرم و درگیری"),intro:e("Crime is encouraged. Lazy crime is not.","جرم تشویق می‌شود؛ جرم بی‌کیفیت خیر."),items:[{n:"3.1",t:e("Robbery needs build-up","سرقت نیاز به مقدمه دارد"),d:e("Approach, demand, escalate. A robbery that starts and ends in four seconds is not roleplay.","نزدیک شدن، درخواست، تشدید."),p:e("1-3 days","۱ تا ۳ روز")},{n:"3.2",t:e("Maximum 6 in a hostile group","حداکثر ۶ نفر در گروه مهاجم"),d:e("No more than six players may act together in an armed conflict, and never more than two crews allied at once.","حداکثر شش بازیکن در یک درگیری مسلحانه."),p:e("3 days for all involved","۳ روز برای همه طرفین")},{n:"3.3",t:e("New Life Rule","قانون زندگی جدید"),d:e("If you are declared dead by EMS, your character forgets the 30 minutes before death and may not return to that scene for one hour.","پس از مرگ، ۳۰ دقیقه قبل فراموش می‌شود."),p:e("3 days","۳ روز")},{n:"3.4",t:e("No combat logging","بدون خروج حین درگیری"),d:e("Disconnecting during an active scene to avoid an outcome is an instant removal. Crashes happen - come back and tell staff.","خروج از بازی در حین صحنه فعال ممنوع است."),p:e("7 days","۷ روز")},{n:"3.5",t:e("Green zones","مناطق امن"),d:e("Hospitals, police stations, the DMV and the city hall are safe. No weapons drawn, no kidnapping, no exceptions.","بیمارستان، کلانتری و شهرداری مناطق امن هستند."),p:e("3 days","۳ روز")}]},{id:"technical",icon:"cpu",title:e("Technical & Fair Play","فنی و بازی منصفانه"),intro:e("Anything that gives you an advantage the game did not intend.","هر چیزی که مزیت غیرمجاز بدهد."),items:[{n:"4.1",t:e("No cheats, menus or injectors","بدون چیت و منو"),d:e("Any modification that reads or writes game memory is an instant permanent ban on every account linked to your hardware.","هر ابزاری که حافظه بازی را تغییر دهد منجر به مسدودی دائم می‌شود."),p:e("Permanent, hardware ID","دائمی، شناسه سخت‌افزار")},{n:"4.2",t:e("Report exploits, do not use them","اشکالات را گزارش دهید"),d:e("Found a dupe or a money bug? Report it and you keep your account and get a reward. Use it and you lose both.","اگر اشکالی پیدا کردید گزارش دهید تا پاداش بگیرید."),p:e("Permanent for abuse","دائمی در صورت سوءاستفاده")},{n:"4.3",t:e("One account per person","یک حساب برای هر نفر"),d:e("Alt accounts to dodge a ban, farm money or stack VIP perks are removed along with the original.","حساب‌های جانبی برای دور زدن مسدودی حذف می‌شوند."),p:e("Permanent on all accounts","دائمی برای تمام حساب‌ها")},{n:"4.4",t:e("No real-money trading","بدون مبادله با پول واقعی"),d:e("Selling in-game assets, accounts or services to other players for real currency is forbidden. The store is the only legitimate route.","فروش دارایی درون‌بازی به بازیکنان دیگر ممنوع است."),p:e("Permanent for both parties","دائمی برای هر دو طرف")}]},{id:"appeals",icon:"clipboard",title:e("Punishments & Appeals","جرایم و تجدیدنظر"),intro:e("How decisions are made and how to challenge one.","چگونگی تصمیم‌گیری و اعتراض."),items:[{n:"5.1",t:e("Every punishment is logged","هر مجازات ثبت می‌شود"),d:e("Bans, kicks and warnings are written to an immutable log with the reason, the evidence and the staff member responsible.","مسدودی‌ها در یک لاگ غیرقابل تغییر ثبت می‌شوند."),p:null},{n:"5.2",t:e("Appeals are free and always open","تجدیدنظر رایگان است"),d:e("Open a ticket under Ban Appeal. A Head Admin who was not involved in the original decision reviews it within 72 hours.","یک تیکت باز کنید؛ در ۷۲ ساعت بررسی می‌شود."),p:null},{n:"5.3",t:e("Nobody can buy leniency","هیچ‌کس نمی‌تواند بخشش بخرد"),d:e("VIP status, donation history and account age have zero weight in a moderation decision. Staff cannot see your spend while reviewing a report.","وی‌آی‌پی و سابقه خرید هیچ تاثیری در تصمیمات ندارد."),p:null}]}],r=[{cat:"start",q:e("How do I join the server?","چگونه به سرور متصل شوم؟"),a:e('Install FiveM, launch GTA V once through it, then either search "Royal RP" in the server list or press F8 in FiveM and paste our connect command. You can copy it from the button at the top of this site.',"ابتدا FiveM را نصب کنید، یک بار GTA V را اجرا کنید، سپس در لیست سرورها Royal RP را جستجو کنید یا در F8 دستور اتصال را وارد کنید.")},{cat:"start",q:e("Do I need a legal copy of GTA V?","آیا به نسخه اصلی GTA V نیاز دارم؟"),a:e("Yes. FiveM requires a legitimate, activated copy of Grand Theft Auto V on Steam, Rockstar Games Launcher or Epic. Pirated copies cannot connect.","بله. FiveM به نسخه قانونی و فعال‌شده نیاز دارد.")},{cat:"start",q:e("Is there a whitelist to get in?","آیا برای ورود وایت‌لیست لازم است؟"),a:e("The city itself is open - connect and play. Specific factions (LSPD, BCSO, EMS, DOJ) are whitelisted and need an application through the support centre.","ورود به شهر آزاد است؛ اما فکشن‌های خاص نیاز به درخواست دارند.")},{cat:"start",q:e("What are the PC requirements?","حداقل سخت‌افزار چیست؟"),a:e("If GTA V runs well for you, Royal RP will too. We recommend 16GB RAM and an SSD, because streamed custom assets load constantly.","اگر GTA V روان اجرا می‌شود، اینجا هم مشکلی ندارید. ۱۶ گیگ رم و دیسک SSD توصیه می‌شود.")},{cat:"shop",q:e("How fast is delivery after I pay?","تحویل چقدر طول می‌کشد؟"),a:e('Automatic items (VIP, cash, slots, plates) land within about 60 seconds of the payment provider confirming. Items marked "manual fulfilment" need a staff member and are handled within 48 hours.',"موارد خودکار حدود ۶۰ ثانیه پس از تایید پرداخت تحویل می‌شوند.")},{cat:"shop",q:e("Is buying required to play?","آیا خرید اجباری است؟"),a:e("No. Everything that affects roleplay quality is free. Purchases cover hosting and development and give convenience, cosmetics and queue priority - never power over other players.","خیر. خریدها فقط راحتی و ظاهر می‌دهند، نه قدرت.")},{cat:"shop",q:e("Can I get a refund?","آیا امکان بازپرداخت وجود دارد؟"),a:e("Yes, within 14 days if the item has not been delivered or does not work as described. Read the full terms on our Refund Policy page.","بله، تا ۱۴ روز اگر آیتم تحویل نشده یا مطابق توصیف نباشد.")},{cat:"shop",q:e("Which payment methods do you accept?","چه روش‌های پرداختی قبول می‌کنید؟"),a:e("Card and PayPal through our payment provider, plus account wallet credit. We never see or store your card details - they go straight to the provider.","کارت و پی‌پال از طریق درگاه پرداخت و اعتبار کیف پول حساب.")},{cat:"shop",q:e("Does VIP transfer between my characters?","آیا VIP بین شخصیت‌ها مشترک است؟"),a:e("VIP is attached to your account, so every character you own benefits. Vehicles and property are per-character.","VIP به حساب شما متصل است و همه شخصیت‌ها از آن بهره می‌برند.")},{cat:"account",q:e("How do I link my game account?","چگونه حساب بازی را متصل کنم؟"),a:e("Sign in with Discord, then connect to the server once. The link happens automatically by matching your Discord ID to your FiveM identifier.","با دیسکورد وارد شوید و یک بار به سرور متصل شوید.")},{cat:"account",q:e("I forgot my password","رمز عبورم را فراموش کردم"),a:e('Use the "Forgot password" link on the sign-in page. If you registered through Discord you do not have a password - just use the Discord button.',"از لینک بازیابی رمز در صفحه ورود استفاده کنید.")},{cat:"account",q:e("Can I delete my account and data?","آیا می‌توانم حساب و داده‌هایم را حذف کنم؟"),a:e("Yes. Open a ticket and we will erase your personal data within 30 days. Moderation records tied to a ban are retained as permitted by law.","بله. یک تیکت باز کنید تا در ۳۰ روز داده‌های شخصی حذف شود.")},{cat:"rules",q:e("I was banned. What now?","مسدود شدم. حالا چه؟"),a:e("Open a ticket under Ban Appeal. A Head Admin who was not involved in the original decision reviews it within 72 hours. Appeals are always free.","یک تیکت تحت دسته تجدیدنظر باز کنید.")},{cat:"rules",q:e("How do I report another player?","چگونه یک بازیکن را گزارش دهم؟"),a:e("Record the clip, note the time and their in-game name, then open a Player Report ticket. Do not confront them out of character in the middle of a scene.","کلیپ ضبط کنید و یک تیکت گزارش بازیکن باز کنید.")},{cat:"rules",q:e("Does buying VIP protect me from bans?","آیا VIP از مسدودی جلوگیری می‌کند؟"),a:e("Absolutely not. Staff cannot even see your purchase history while reviewing a report. Rules apply identically to everyone.","قطعاً خیر. قوانین برای همه یکسان است.")},{cat:"tech",q:e("I keep getting texture loss","مدام افت تکسچر دارم"),a:e("Lower your texture quality one step, cap your FPS to your monitor refresh rate, and make sure GTA V is installed on an SSD. Texture loss is almost always VRAM exhaustion.","کیفیت تکسچر را یک پله کم کنید و FPS را محدود کنید.")},{cat:"tech",q:e("My ping is high from Iran","پینگ من از ایران بالاست"),a:e("The server is in Frankfurt. From Tehran, 90-140ms is normal and perfectly playable. If you see 250ms+, a routing issue is likely - open a ticket and we will look at your traceroute.","سرور در فرانکفورت است. پینگ ۹۰ تا ۱۴۰ طبیعی است.")},{cat:"tech",q:e("The server is full. How does the queue work?","صف چگونه کار می‌کند؟"),a:e("The queue is first-come, first-served, with priority slots reserved for VIP and on-duty whitelisted staff. Your place is kept if you disconnect within 3 minutes.","صف به ترتیب ورود است با اسلات‌های اولویت‌دار برای VIP.")}],i=[{id:"all",name:e("All questions","همه سؤالات")},{id:"start",name:e("Getting started","شروع کار")},{id:"shop",name:e("Store & payments","فروشگاه و پرداخت")},{id:"account",name:e("Account","حساب کاربری")},{id:"rules",name:e("Rules & moderation","قوانین")},{id:"tech",name:e("Technical","فنی")}],s={lead:e("Royal RP started in 2023 as four people who were tired of servers where money appeared from nowhere and nobody stayed in character past the first gunshot. We built the city we wanted to play in.","رویال آر‌پی در سال ۲۰۲۳ با چهار نفر شروع شد که از سرورهایی خسته بودند که در آن‌ها پول از ناکجا می‌آمد."),story:[{h:e("What we are","ما چه هستیم"),p:e("A serious-roleplay FiveM server built on a custom framework over ESX, running on dedicated hardware in Frankfurt. Around 19,000 people are in the Discord and between 60 and 240 of them are in the city at any given hour.","یک سرور رول‌پلی جدی بر پایه فریم‌ورک اختصاصی روی ESX.")},{h:e("What we are not","ما چه نیستیم"),p:e("We are not pay-to-win, we are not a deathmatch server with a police job bolted on, and we are not affiliated with Rockstar Games or Cfx.re in any way.","ما پی‌تو‌وین نیستیم و هیچ وابستگی به Rockstar یا Cfx.re نداریم.")},{h:e("Where the money goes","پول کجا می‌رود"),p:e("Hosting, the database server, asset licences, and paying the two developers who work on this part-time. Nobody is getting rich here - the finances are summarised in Discord every quarter.","هاستینگ، سرور دیتابیس، لایسنس دارایی‌ها و حقوق دو توسعه‌دهنده.")}],timeline:[{date:"2023-02",h:e("The server opens","سرور باز می‌شود"),p:e("32 slots, one developer, a borrowed ESX base and 40 regulars.","۳۲ اسلات، یک توسعه‌دهنده.")},{date:"2023-09",h:e("Custom framework","فریم‌ورک اختصاصی"),p:e("We stop patching other people’s scripts and write our own core.","نوشتن هسته اختصاصی.")},{date:"2024-04",h:e("Whitelisted services","خدمات وایت‌لیست"),p:e("LSPD and EMS move to a trained, assessed intake model.","پلیس و اورژانس به مدل آموزشی منتقل می‌شوند.")},{date:"2025-01",h:e("256 slots","۲۵۶ اسلات"),p:e("New hardware, 256 slots and the housing market goes live.","سخت‌افزار جدید و بازار مسکن.")},{date:"2026-10",h:e("Season Four","فصل چهارم"),p:e("Full economy rebuild and fourteen new interiors.","بازسازی کامل اقتصاد.")}],values:[{icon:"shield",h:e("Consistency over spectacle","ثبات بر نمایش"),p:e("A believable city beats a loud one. We would rather lose a dramatic moment than break the fiction.","یک شهر باورپذیر بهتر از یک شهر پرسروصداست.")},{icon:"eye",h:e("Transparency by default","شفافیت به صورت پیش‌فرض"),p:e("Every moderation action is logged, every economy change is published, and the quarterly finances are posted in Discord.","هر اقدام مدیریتی ثبت و منتشر می‌شود.")},{icon:"heart",h:e("No pay-to-win, ever","هرگز پی‌تو‌وین نخواهیم شد"),p:e("Nothing in the store gives you an advantage in a conflict with another player. That line does not move.","هیچ چیزی در فروشگاه مزیت درگیری نمی‌دهد.")},{icon:"globe",h:e("Two languages, one city","دو زبان، یک شهر"),p:e("Persian and English players share the same city, the same rules and the same staff availability.","بازیکنان فارسی و انگلیسی‌زبان در یک شهر مشترک‌اند.")}]},o="2026-10-01",d={terms:{updated:o,title:e("Terms of Service","شرایط استفاده"),intro:e("These terms govern your use of the Royal RP website and game server. By connecting or buying anything, you accept them.","این شرایط ناظر بر استفاده شما از وب‌سایت و سرور رویال آر‌پی است."),sections:[{id:"eligibility",h:e("1. Eligibility","۱. شرایط واجدین"),body:e(["You must be at least 16 years old to use this service.","You must own a legitimate, activated copy of Grand Theft Auto V.","You are responsible for everything that happens under your account, including purchases made by anyone you give access to."],["شما باید حداقل ۱۶ سال داشته باشید.","باید نسخه قانونی GTA V داشته باشید.","مسئولیت تمام فعالیت‌های حساب شما بر عهده خودتان است."])},{id:"conduct",h:e("2. Acceptable use","۲. استفاده مجاز"),body:e(["You agree to follow the server rules published on this site. They form part of these terms.","You may not use cheats, exploits, automation or any software that modifies the game client.","You may not resell, trade or transfer in-game assets or accounts for real-world value.","You may not attempt to access, probe or disrupt our infrastructure."],["شما موافقت می‌کنید قوانین سرور را رعایت کنید.","استفاده از چیت و ابزارهای تقلب ممنوع است.","فروش دارایی‌های درون‌بازی ممنوع است.","تلاش برای نفوذ به زیرساخت ممنوع است."])},{id:"purchases",h:e("3. Purchases and virtual items","۳. خرید و آیتم‌های مجازی"),body:e(["All purchases are voluntary contributions toward hosting and development costs.","Virtual items are a revocable licence to use content on our server. They are not property, carry no real-world value and cannot be sold.","Items may be modified or removed when the server is rebalanced. Where an item is removed permanently, we offer equivalent value or a refund.","A banned account forfeits access to purchased items. Refunds are not issued for items lost to a ban caused by a rule breach."],["تمام خریدها کمک داوطلبانه به هزینه‌های سرور هستند.","آیتم‌های مجازی مالکیت نیستند و ارزش واقعی ندارند.","آیتم‌ها ممکن است در بازنگری تغییر کنند.","حساب مسدودشده دسترسی به آیتم‌ها را از دست می‌دهد."])},{id:"moderation",h:e("4. Moderation","۴. مدیریت و نظارت"),body:e(["We may warn, kick, suspend or permanently remove any account that breaks the rules.","Moderation decisions are logged and can be appealed free of charge through the support centre.","Purchase history has no influence on a moderation decision."],["ما می‌توانیم حساب متخلف را محدود یا حذف کنیم.","تصمیمات قابل تجدیدنظر رایگان هستند.","سابقه خرید هیچ تاثیری ندارد."])},{id:"liability",h:e("5. Availability and liability","۵. دسترس‌پذیری و مسئولیت"),body:e(['The service is provided "as is". We aim for 99.9% uptime but do not guarantee uninterrupted availability.',"We are not liable for lost in-game progress, items or currency caused by outages, bugs or third-party failures, beyond restoring from our most recent backup.","Nothing in these terms limits liability that cannot be limited by law."],["سرویس به صورت «همان‌گونه که هست» ارائه می‌شود.","مسئولیت ما به بازگردانی از آخرین نسخه پشتیبان محدود است.","هیچ بندی مسئولیت‌های قانونی را سلب نمی‌کند."])},{id:"ip",h:e("6. Intellectual property","۶. مالکیت فکری"),body:e(["Grand Theft Auto V is the property of Rockstar Games. FiveM and Cfx.re are the property of their respective owners. Royal RP is an independent community project and is not affiliated with, endorsed by or sponsored by any of them.","Our own scripts, artwork, branding and written content remain our property."],["GTA V متعلق به Rockstar Games است. رویال آر‌پی یک پروژه مستقل است.","اسکریپت‌ها و طراحی‌های ما متعلق به خودمان است."])},{id:"changes",h:e("7. Changes to these terms","۷. تغییرات"),body:e(["We will announce material changes in Discord and on this page at least 14 days before they take effect."],["تغییرات مهم حداقل ۱۴ روز قبل اعلام می‌شوند."])}]},privacy:{updated:o,title:e("Privacy Policy","سیاست حریم خصوصی"),intro:e("What we collect, why we collect it, how long we keep it, and how to get it deleted.","چه داده‌ای جمع می‌کنیم، چرا، چقدر نگه می‌داریم و چگونه حذف می‌شود."),sections:[{id:"collect",h:e("1. What we collect","۱. چه داده‌ای جمع می‌کنیم"),body:e(["Account data: email address, username, password hash (bcrypt - never the password itself), and your Discord ID if you link it.","Game data: your FiveM identifiers (license, steam, discord), character names, in-game assets and playtime.","Order data: what you bought, when, the amount and the payment provider’s transaction reference. We never receive or store card numbers.","Technical data: IP address, browser user-agent and timestamps, kept for security and abuse prevention."],["داده حساب: ایمیل، نام کاربری، هش رمز عبور و شناسه دیسکورد.","داده بازی: شناسه‌های FiveM، نام شخصیت‌ها و زمان بازی.","داده سفارش: موارد خریداری‌شده و مرجع تراکنش. شماره کارت هرگز ذخیره نمی‌شود.","داده فنی: آدرس آی‌پی و زمان دسترسی."])},{id:"why",h:e("2. Why we collect it","۲. چرا جمع می‌کنیم"),body:e(["To run your account and deliver what you purchased (contractual necessity).","To moderate the community and prevent cheating, fraud and abuse (legitimate interest).","To meet accounting and tax obligations on purchases (legal obligation)."],["برای اداره حساب و تحویل خرید شما.","برای نظارت بر جامعه و جلوگیری از تقلب.","برای انجام تعهدات قانونی و مالیاتی."])},{id:"retention",h:e("3. How long we keep it","۳. مدت نگهداری"),body:e(["Account data: until you ask us to delete it.","Security and connection logs: 90 days, then automatically purged.","Order and invoice records: 7 years, because tax law requires it.","Moderation records attached to a permanent ban: retained while the ban stands."],["داده حساب: تا زمان درخواست حذف.","لاگ‌های امنیتی: ۹۰ روز.","سوابق مالی: ۷ سال طبق قانون.","سوابق مدیریتی: تا زمان برقراری مسدودی."])},{id:"sharing",h:e("4. Who we share it with","۴. اشتراک‌گذاری"),body:e(["Our payment provider, to process your payment.","Our hosting provider, which stores the data on our behalf.","Discord, if you choose to sign in with it.","We never sell your data, and we do not run advertising or analytics trackers."],["درگاه پرداخت برای پردازش پرداخت.","ارائه‌دهنده هاستینگ.","دیسکورد، در صورت ورود با آن.","ما هرگز داده شما را نمی‌فروشیم."])},{id:"cookies",h:e("5. Cookies and storage","۵. کوکی و ذخیره‌سازی"),body:e(["We set one httpOnly session cookie to keep you signed in and one CSRF token cookie to protect form submissions. Both are strictly necessary.","Your cart and language preference are stored in your browser’s localStorage and never leave your device.","We do not use advertising, profiling or third-party analytics cookies."],["یک کوکی نشست و یک توکن CSRF که هر دو ضروری هستند.","سبد خرید و زبان در مرورگر شما ذخیره می‌شوند.","هیچ کوکی تبلیغاتی استفاده نمی‌شود."])},{id:"rights",h:e("6. Your rights","۶. حقوق شما"),body:e(["You can request a copy of your data, correct it, or have it erased. Open a ticket and we respond within 30 days.","You can object to processing based on legitimate interest.","If you are in the EEA or UK you may complain to your local data protection authority."],["می‌توانید نسخه‌ای از داده‌هایتان را درخواست، اصلاح یا حذف کنید.","می‌توانید به پردازش اعتراض کنید.","امکان شکایت به مرجع حفاظت از داده وجود دارد."])},{id:"security",h:e("7. How we protect it","۷. حفاظت از داده"),body:e(["Passwords are hashed with bcrypt and never stored or logged in plain text.","All traffic is served over HTTPS. Session cookies are httpOnly, Secure and SameSite.","Database access is restricted to the application, with parameterised queries only.","Administrative actions are rate-limited, permission-checked server-side and written to an audit log."],["رمزهای عبور با bcrypt هش می‌شوند.","تمام ترافیک روی HTTPS است.","دسترسی دیتابیس محدود و با کوئری پارامتری است.","اقدامات مدیریتی در لاگ ثبت می‌شوند."])}]},refund:{updated:o,title:e("Refund Policy","سیاست بازپرداخت"),intro:e("We would rather fix the problem than keep money you are unhappy about. Here is exactly when we refund.","ترجیح ما حل مشکل است. اینجا دقیقاً مشخص شده چه زمانی بازپرداخت می‌کنیم."),sections:[{id:"eligible",h:e("1. When you get a full refund","۱. بازپرداخت کامل"),body:e(["The item was never delivered and we cannot deliver it.","The item does not work as described and we cannot fix it within 7 days.","You were charged twice for the same order.","The purchase was made without your authorisation (we will also secure your account).","You changed your mind within 14 days AND the item has not been delivered or used."],["آیتم تحویل نشده و قابل تحویل نیست.","آیتم مطابق توصیف کار نمی‌کند و تا ۷ روز رفع نشد.","دو بار هزینه از شما کسر شده است.","خرید بدون اجازه شما انجام شده است.","تا ۱۴ روز نظرتان عوض شده و آیتم تحویل نشده است."])},{id:"not",h:e("2. When we cannot refund","۲. موارد غیرقابل بازپرداخت"),body:e(["The item was delivered and used, and works as described.","Your account was banned for breaking the rules.","More than 14 days have passed and the item was delivered correctly.","The request is for a consumed item such as in-game cash that has already been spent.","Chargebacks filed without contacting us first result in the account being suspended until resolved."],["آیتم تحویل و استفاده شده و سالم است.","حساب شما به دلیل تخلف مسدود شده است.","بیش از ۱۴ روز گذشته و تحویل درست بوده است.","آیتم مصرف‌شدنی مانند پول درون‌بازی خرج شده است.","ثبت چارج‌بک بدون تماس قبلی منجر به تعلیق حساب می‌شود."])},{id:"how",h:e("3. How to request one","۳. روش درخواست"),body:e(['Open a ticket under "Billing & orders" with your order number (RR-xxxxx).',"Tell us what went wrong. Screenshots help but are not required.","We respond within 48 hours. Approved refunds reach your original payment method in 5-10 business days.","If an item was removed in a server rebalance, you may choose store credit of equal value instead."],["یک تیکت در دسته پرداخت با شماره سفارش باز کنید.","مشکل را توضیح دهید.","تا ۴۸ ساعت پاسخ می‌دهیم و بازپرداخت در ۵ تا ۱۰ روز کاری انجام می‌شود.","در صورت حذف آیتم در بازنگری، اعتبار معادل ارائه می‌شود."])},{id:"consumer",h:e("4. Your statutory rights","۴. حقوق قانونی شما"),body:e(["Nothing in this policy limits consumer protection rights you have under the law of your country.","EU and UK customers: digital content delivered immediately with your express consent waives the 14-day withdrawal right for that item. We state this clearly at checkout."],["این سیاست حقوق قانونی شما را محدود نمی‌کند.","محتوای دیجیتال تحویل‌شده فوری با رضایت صریح شما مشمول حق انصراف ۱۴ روزه نیست."])}]}};function c(t,a){return t==null?"":typeof t=="object"&&("en"in t||"fa"in t)?t[a]??t.en??t.fa??"":t}export{n as a,r as b,i as c,s as d,d as e,c as f};
